import { applyEdits, findNodeAtLocation, format, getNodeValue, modify, parseTree } from "jsonc-parser"

export const SCHEMA = "https://opencode.ai/config.json"

function options(text) {
  return {
    formattingOptions: {
      insertSpaces: true,
      tabSize: 2,
      eol: text.includes("\r\n") ? "\r\n" : "\n",
    },
  }
}

function clean(text) {
  return text.replace(/^\uFEFF/, "")
}

function matches(entry, pkg, url) {
  if (typeof entry === "string") return entry === pkg || entry.startsWith(pkg + "@")
  if (entry && typeof entry === "object") {
    if (typeof entry.package === "string" && entry.package === pkg) return true
    if (url && entry.options && entry.options.url === url) return true
  }
  return false
}

export function upsertPlugin(text, pkg, entry) {
  const source = clean(text)
  if (!source.trim()) {
    return JSON.stringify({ $schema: SCHEMA, plugins: [entry] }, null, 2) + "\n"
  }
  const tree = parseTree(source, [], { allowTrailingComma: true })
  if (!tree) throw new Error("opencode config is not valid JSON")

  const node = findNodeAtLocation(tree, ["plugins"])
  const plugins = node ? getNodeValue(node) : undefined
  const opts = options(source)
  const url = entry && typeof entry === "object" && entry.options ? entry.options.url : undefined
  let edits

  if (Array.isArray(plugins)) {
    const index = plugins.findIndex((item) => matches(item, pkg, url))
    const target = index >= 0 ? index : plugins.length
    edits = modify(source, ["plugins", target], entry, opts)
  } else {
    edits = modify(source, ["plugins"], [entry], opts)
  }
  const edited = applyEdits(source, edits)
  return applyEdits(edited, format(edited, undefined, opts.formattingOptions))
}

export function removePlugin(text, pkg) {
  const source = clean(text)
  const tree = parseTree(source, [], { allowTrailingComma: true })
  if (!tree) throw new Error("opencode config is not valid JSON")

  const node = findNodeAtLocation(tree, ["plugins"])
  const plugins = node ? getNodeValue(node) : undefined
  if (!Array.isArray(plugins)) return source

  const index = plugins.findIndex((item) => matches(item, pkg))
  if (index < 0) return source
  const edited = applyEdits(source, modify(source, ["plugins", index], undefined, options(source)))
  return applyEdits(edited, format(edited, undefined, options(source).formattingOptions))
}

#!/usr/bin/env node
import { constants } from "node:fs"
import { access, copyFile, mkdir, readFile, writeFile } from "node:fs/promises"
import { homedir } from "node:os"
import { dirname, join } from "node:path"
import { removePlugin, upsertPlugin } from "./config-edit.mjs"

const DEFAULT_PACKAGE = "@racfor/oc-remote"

async function main() {
  const args = process.argv.slice(2)
  const command = args.shift()
  if (!command || command === "help" || command === "--help" || command === "-h") {
    help()
    return
  }
  if (command === "join") {
    await joinCommand(args)
    return
  }
  if (command === "leave") {
    await leaveCommand(args)
    return
  }
  throw new Error(`unknown command: ${command}`)
}

function parseFlags(args) {
  const out = { positional: [], name: "", pkg: DEFAULT_PACKAGE, help: false }
  for (let i = 0; i < args.length; i++) {
    const arg = args[i]
    if (arg === "--name" || arg === "-n") {
      out.name = args[++i] ?? ""
      continue
    }
    if (arg.startsWith("--name=")) {
      out.name = arg.slice("--name=".length)
      continue
    }
    if (arg === "--package" || arg === "-p") {
      out.pkg = args[++i] ?? ""
      continue
    }
    if (arg.startsWith("--package=")) {
      out.pkg = arg.slice("--package=".length)
      continue
    }
    if (arg === "--help" || arg === "-h") {
      out.help = true
      continue
    }
    if (arg.startsWith("-")) throw new Error(`unknown flag: ${arg}`)
    out.positional.push(arg)
  }
  return out
}

function normalizeUrl(raw) {
  const url = new URL(raw)
  if (url.protocol !== "https:" && url.protocol !== "http:") {
    throw new Error("url must start with https:// or http://")
  }
  url.pathname = "/"
  url.search = ""
  url.hash = ""
  return url.origin
}

async function joinCommand(args) {
  const flags = parseFlags(args)
  if (flags.help) {
    help()
    return
  }
  if (!flags.pkg) throw new Error("--package needs a value")
  const [rawUrl, key] = flags.positional
  if (!rawUrl || !key) {
    throw new Error("usage: oc-remote join <url> <key> [--name <device>] [--package <pkg>]")
  }
  const url = normalizeUrl(rawUrl)
  await health(url)
  const verified = await verify(url, key)
  const config = await configPath()
  const text = await readText(config)
  const entry = {
    package: flags.pkg,
    options: { url, key, ...(flags.name ? { name: flags.name } : {}) },
  }
  await backup(config)
  await mkdir(dirname(config), { recursive: true })
  await writeFile(config, upsertPlugin(text, flags.pkg, entry), "utf8")
  console.log(`Configured ${verified.tenant}/${verified.device} at ${url}`)
  console.log(`Plugin entry: ${config}`)
  console.log("Run /remote in the OpenCode TUI.")
}

async function leaveCommand(args) {
  const flags = parseFlags(args)
  if (flags.help) {
    help()
    return
  }
  const config = await configPath()
  const text = await readText(config)
  if (!text) {
    console.log("No OpenCode config found.")
    return
  }
  await backup(config)
  await mkdir(dirname(config), { recursive: true })
  await writeFile(config, removePlugin(text, flags.pkg), "utf8")
  console.log(`Removed ${flags.pkg} from ${config}`)
}

async function health(url) {
  const res = await fetch(url + "/_ocr/healthz", { signal: AbortSignal.timeout(10000) })
  if (!res.ok) throw new Error(`relay health failed: ${res.status} ${res.statusText}`)
  const body = await res.json().catch(() => ({}))
  if (!body || body.ok !== true) throw new Error("relay health returned an unexpected response")
}

async function verify(url, key) {
  const res = await fetch(url + "/_ocr/api/verify", {
    method: "POST",
    headers: { authorization: "Bearer " + key },
    signal: AbortSignal.timeout(10000),
  })
  if (!res.ok) {
    const text = await res.text().catch(() => "")
    throw new Error(`device key rejected: ${res.status} ${text}`.trim())
  }
  const body = await res.json()
  if (typeof body?.tenant !== "string" || typeof body?.device !== "string") {
    throw new Error("relay verify returned an unexpected response")
  }
  return { tenant: body.tenant, device: body.device }
}

async function configPath() {
  const base = process.env.XDG_CONFIG_HOME || join(homedir(), ".config")
  const dir = join(base, "opencode")
  const json = join(dir, "opencode.json")
  const jsonc = join(dir, "opencode.jsonc")
  if (await exists(json)) return json
  if (await exists(jsonc)) return jsonc
  return json
}

async function readText(path) {
  try {
    return await readFile(path, "utf8")
  } catch (error) {
    if (error && error.code === "ENOENT") return ""
    throw error
  }
}

async function backup(path) {
  if (!(await exists(path))) return
  const backupPath = path + ".bak"
  if (await exists(backupPath)) return
  await copyFile(path, backupPath)
}

async function exists(path) {
  try {
    await access(path, constants.F_OK)
    return true
  } catch {
    return false
  }
}

function help() {
  console.log(`oc-remote — remote access for a local OpenCode v2 server

Usage:
  oc-remote join <url> <key> [--name <device>] [--package <pkg>]
  oc-remote leave [--package <pkg>]

Examples:
  oc-remote join https://rc.addies.ai ocr_...
  oc-remote join http://127.0.0.1:4097 ocr_... --package file:///D:/Source/oc-remote/plugin

The join command writes the plugin and its options into the global opencode.json
(comments and unrelated settings are preserved) and keeps a .bak copy.`)
}

main().catch((error) => {
  console.error(error instanceof Error ? error.message : String(error))
  process.exit(1)
})

import { Plugin } from "@opencode/plugin"
import { OcRemoteRpc } from "./rpc.js"
import { Tunnel } from "./tunnel.js"

type Shared = {
  tunnel: Tunnel
  refs: number
}

type Global = typeof globalThis & {
  __ocRemoteShared?: Shared
  __ocRemoteSeen?: Set<string>
}

const global = globalThis as Global

function acquire(url: string, key: string, name?: string): Shared {
  if (!global.__ocRemoteShared) {
    const tunnel = new Tunnel({ url, key, name })
    tunnel.start()
    global.__ocRemoteShared = { tunnel, refs: 0 }
  }
  const state = global.__ocRemoteShared
  state.refs++
  return state
}

function release(state: Shared): void {
  state.refs--
  if (state.refs > 0) return
  state.tunnel.stop()
  if (global.__ocRemoteShared === state) delete global.__ocRemoteShared
}

function remember(id: string): boolean {
  const seen = (global.__ocRemoteSeen ??= new Set<string>())
  if (seen.has(id)) return false
  seen.add(id)
  if (seen.size > 512) {
    const first = seen.values().next().value
    if (first !== undefined) seen.delete(first)
  }
  return true
}

export default Plugin.define({
  id: "oc-remote",
  async setup(ctx) {
    const url = typeof ctx.options.url === "string" ? ctx.options.url.trim() : ""
    const key = typeof ctx.options.key === "string" ? ctx.options.key.trim() : ""
    const name = typeof ctx.options.name === "string" ? ctx.options.name : undefined
    const state = url && key ? acquire(url, key, name) : null

    const registration = await ctx.rpc.register(OcRemoteRpc, {
      status: async () =>
        state
          ? state.tunnel.status()
          : {
              configured: false,
              online: false,
              url: "",
              device: "",
              tenant: "",
              error: "run npx @racfor/oc-remote join <url> <key>",
            },
      pair: async () => {
        if (!state) throw new Error("oc-remote is not configured")
        return state.tunnel.mintAndRegister()
      },
      off: async () => {
        state?.tunnel.stop()
        return {}
      },
      on: async () => {
        state?.tunnel.start()
        return {}
      },
    })

    const controller = state ? new AbortController() : null
    if (state && controller) {
      void (async () => {
        try {
          for await (const event of ctx.event.subscribe({
            types: ["permission.asked"],
            signal: controller.signal,
          })) {
            if (remember(event.id)) state.tunnel.notifyPermission(event.data)
          }
        } catch {}
      })()
    }

    return async () => {
      controller?.abort()
      await registration.dispose()
      if (state) release(state)
    }
  },
})
